fun apply(e: Entry): List<Diff> {
    val t = e.transfer
    balances.merge(t.from, -t.cents, Long::plus)
    balances.merge(t.to, t.cents, Long::plus)
    return listOf(Diff(e.offset, t.from, -t.cents), Diff(e.offset, t.to, t.cents))
}

fun readAfter(account: String, offset: Long, reply: (Read) -> Unit) {
    if (applied >= offset) reply(readNow(account))
    else parked += Parked(account, offset, reply)
}

private fun releaseParked() {
    val ready = parked.filter { it.offset <= applied }
    parked.removeAll(ready)
    for (p in ready) p.reply(readNow(p.account))
}

fun receive(d: Diff) {
    if (d.offset <= lastOffset) { ignored++; return }   // repeat, or already in the snapshot
    balance += d.delta
    lastOffset = d.offset
    applied++
}

