fun readAfter(account: String, offset: Long, reply: (Read) -> Unit) {
    if (applied >= offset) reply(readNow(account))      // the view already has the write
    else parked += Parked(account, offset, reply)       // wait for the poll that applies it
}

// after each poll has applied everything new:
val ready = parked.filter { it.offset <= applied }
parked.removeAll(ready)                                 // each read answered exactly once
for (p in ready) p.reply(readNow(p.account))

// client: apply a diff only if it's newer than the last one applied
if (d.offset > lastOffset) { balance += d.delta; lastOffset = d.offset }
